mapper.select:
drop temporary table if exists `temp_update_permission`;

 create temporary table `temp_update_permission` (
 `id` INT AUTO_INCREMENT PRIMARY KEY ,
 `sub_per` text,
`must_subject_json` text,
`may_subject_json` text
)
 ; 

INSERT INTO temp_update_permission(id,sub_per,must_subject_json,may_subject_json)
VALUES

    (#{item.id},#{item.subPermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler},#{item.mustSubjectJson,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler},
     #{item.maySubjectJson,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler})

;
update gc_user_access_permission uap,temp_update_permission temp
set uap.sub_permission=temp.sub_per,
uap.must_subject_json = temp.must_subject_json,
uap.may_subject_json = temp.may_subject_json
WHERE temp.id=uap.id;

select row_count();

select * from gc_user_access_permission per
left join gc_user_access ua on ua.id = per.user_access_id
where ua.master_id = #{masterId}

