drop temporary table if exists `temp_update_permission`;

 create temporary table `temp_update_permission` (
 `id` INT AUTO_INCREMENT PRIMARY KEY ,
 `sub_per` text,
`channel_permission` text,
`subscribe_permission` text
)
 ; 
INSERT INTO temp_update_permission(id,sub_per,channel_permission,subscribe_permission)
VALUES

    (#{item.id},#{item.subPermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler},
    #{item.channelPermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler},
    #{item.subscribePermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler}
    )

;
update gc_user_access_permission uap,temp_update_permission temp
set
uap.channel_permission = temp.channel_permission,
uap.subscribe_permission = temp.subscribe_permission
WHERE temp.id=uap.id;
select row_count();

update gc_user_access_permission p left join gc_user_access uac on uac.id = p.user_access_id left join gc_access ac on ac.id = uac.access_id
set p.sub_permission = ac.subject_json, p.channel_permission = ac.channel_json, p.must_subject_json = ac.must_subject_json, p.may_subject_json = ac.may_subject_json, p.subscribe_permission = ac.subscribe_json
where 1=1
and ac.master_id = #{masterId}
and uac.user_id = #{userId}

mapper.select:
select count(a.id)
from (
         select acc.*, per.sub_permission, count(acc.id)
         from gc_user_access acc
                  LEFT JOIN gc_user_access_permission per on per.user_access_id = acc.id
                  LEFT JOIN gc_subject s
                            on JSON_CONTAINS(per.sub_permission, CONVERT(s.id, CHAR)) = 1
         where s.master_id = #{masterId}
         GROUP BY acc.id
     )a
